<?php
require_once __DIR__ . '/../includes/auth-check.php'; require_role('customer');
$stmt=db()->prepare("SELECT a.*,s.name salon_name,sv.name service_name,st.name staff_name FROM appointments a JOIN salons s ON s.id=a.salon_id JOIN services sv ON sv.id=a.service_id JOIN staff st ON st.id=a.staff_id WHERE a.customer_id=? ORDER BY a.appointment_date DESC,a.start_time DESC"); $stmt->execute([current_user()['id']]); $appointments=$stmt->fetchAll(); $page_title='My appointments'; include __DIR__.'/../includes/header.php';
?><main class="dashboard-shell"><div class="container"><div class="d-flex justify-content-between align-items-end mb-4"><div><div class="section-label">Your time</div><h1 class="display-5 mb-0">My appointments</h1></div><a class="btn btn-brand" href="<?= e(url('salons.php')) ?>">Book a new visit</a></div><div class="dashboard-card p-3 p-md-4"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Booking</th><th>Salon & service</th><th>When</th><th>Amount</th><th>Status</th></tr></thead><tbody><?php foreach($appointments as $appointment): ?><tr><td><strong><?= e($appointment['booking_code']) ?></strong><small class="d-block muted"><?= e($appointment['staff_name']) ?></small></td><td><?= e($appointment['salon_name']) ?><small class="d-block muted"><?= e($appointment['service_name']) ?></small></td><td><?= date('d M Y',strtotime($appointment['appointment_date'])) ?><small class="d-block muted"><?= date('g:i A',strtotime($appointment['start_time'])) ?></small></td><td><?= money($appointment['amount']) ?></td><td><span class="pill"><?= e(ucfirst($appointment['status'])) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$appointments): ?><div class="text-center py-5"><h2>Your chair is waiting.</h2><p class="muted">Your upcoming appointments will appear here.</p></div><?php endif; ?></div></div></main><?php include __DIR__.'/../includes/footer.php'; ?>
